package com.tianmu.agent.memory;

/** Shared predicate for source alias s. Natural retention never silently extends derived facts. */
public final class MemorySources {
    private MemorySources(){}
    public static final String READABLE="s.status='ACTIVE' AND (s.source_kind IN ('MANUAL','EXPLICIT_DECLARATION') OR (s.source_expires_at>UTC_TIMESTAMP(6) AND EXISTS (SELECT 1 FROM agent_run ar JOIN agent_session ss ON ss.tenant_id=ar.tenant_id AND ss.session_id=ar.session_id WHERE ar.tenant_id=s.tenant_id AND ar.owner_user_id=s.owner_user_id AND ar.run_id=s.origin_run_id AND ar.data_expires_at>UTC_TIMESTAMP(6) AND ss.status='OPEN' AND ss.expires_at>UTC_TIMESTAMP(6)))) AND (s.origin_message_id IS NULL OR EXISTS(SELECT 1 FROM agent_message sm WHERE sm.tenant_id=s.tenant_id AND sm.owner_user_id=s.owner_user_id AND sm.message_id=s.origin_message_id AND sm.run_id=s.origin_run_id AND sm.content_sha256=s.origin_message_hash AND sm.expires_at>UTC_TIMESTAMP(6)))";
    /** Both policies require a witness; V2 additionally requires EVERY necessary source. Alias r is a revision. */
    public static final String REVISION_READABLE="EXISTS(SELECT 1 FROM agent_memory_dependency d JOIN agent_memory_source s ON s.tenant_id=d.tenant_id AND s.owner_user_id=d.owner_user_id AND s.source_id=d.source_id WHERE d.tenant_id=r.tenant_id AND d.owner_user_id=r.owner_user_id AND d.memory_id=r.memory_id AND d.version=r.version AND "+READABLE+") AND (r.support_policy='LEGACY_V1' OR (r.support_policy='ALL_REQUIRED_V2' AND NOT EXISTS(SELECT 1 FROM agent_memory_dependency d LEFT JOIN agent_memory_source s ON s.tenant_id=d.tenant_id AND s.owner_user_id=d.owner_user_id AND s.source_id=d.source_id WHERE d.tenant_id=r.tenant_id AND d.owner_user_id=r.owner_user_id AND d.memory_id=r.memory_id AND d.version=r.version AND COALESCE(("+READABLE+"),0)=0)))";
}
